def transform(grid):
    from math import gcd
    from functools import reduce

    h, w = len(grid), len(grid[0])
    cells8 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    r0 = min(r for r, c in cells8)
    r1 = max(r for r, c in cells8)
    c0 = min(c for r, c in cells8)
    c1 = max(c for r, c in cells8)

    lengths = []
    for row in grid:
        run = 0
        for c in range(w + 1):
            if c < w and row[c] == 8:
                run += 1
            elif run:
                lengths.append(run)
                run = 0
    for c in range(w):
        run = 0
        for r in range(h + 1):
            if r < h and grid[r][c] == 8:
                run += 1
            elif run:
                lengths.append(run)
                run = 0
    unit = reduce(gcd, lengths)

    key = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (0, 8)]
    kr0 = min(r for r, c in key)
    kr1 = max(r for r, c in key)
    kc0 = min(c for r, c in key)
    kc1 = max(c for r, c in key)
    mat = [row[kc0:kc1 + 1] for row in grid[kr0:kr1 + 1]]
    rotated = [list(row) for row in zip(*mat[::-1])]

    out = [row[:] for row in grid]
    for r in range(r0, r1 + 1, unit):
        for c in range(c0, c1 + 1, unit):
            ri = (r - r0) // unit
            ci = (c - c0) // unit
            if ri < len(rotated) and ci < len(rotated[0]) and grid[r][c] == 8:
                color = rotated[ri][ci]
                if color:
                    for dr in range(unit):
                        for dc in range(unit):
                            if r + dr < h and c + dc < w and grid[r + dr][c + dc] == 8:
                                out[r + dr][c + dc] = color
    return out
